// HelperServer is the server API for Helper service.
// All implementations must embed UnimplementedHelperServer
// for forward compatibility.
//
// The privileged helper: one rpc per operation. Reply shapes:
//
//   - `stream TaskEvent` — every mutation, plus the reads whose payload is a
//     foreign tool's output (SmartReport dumps smartctl, LvmReport streams
//     lvm's JSON, RdmaResources streams the rdma tool's JSON). Recorded as a
//     task: Started/Stdout/Stderr/Finished frames the web persists.
//   - typed replies — the structural reads: the daemon reads the canonical
//     system paths and answers with the shared actual-state DTO as a proto
//     message (no JSON-on-stdout round trip).
//   - `Ping`/`Authenticate` — one-shot, never recorded (a task records its
//     request, so recording Authenticate would write the password into the
//     task log).
//
// The daemon-side rule for adding ops: one rpc = one user-level intent. An op
// whose only caller would be a client-side sequence belongs in the daemon as
// part of an existing rpc (see PartitionShrink).
type HelperServer interface {
	// One-shot (never recorded).
	Ping(context.Context, *Empty) (*Empty, error)
	Authenticate(context.Context, *Authenticate) (*AuthReply, error)
	// ZFS zvols and snapshots (reads happen unprivileged in greendot-web).
	ZvolCreate(*ZvolCreate, grpc.ServerStreamingServer[TaskEvent]) error
	ZvolDelete(*ZvolDelete, grpc.ServerStreamingServer[TaskEvent]) error
	ZvolResize(*ZvolResize, grpc.ServerStreamingServer[TaskEvent]) error
	SnapshotCreate(*SnapshotCreate, grpc.ServerStreamingServer[TaskEvent]) error
	SnapshotDestroy(*SnapshotDestroy, grpc.ServerStreamingServer[TaskEvent]) error
	// ZFS filesystem datasets (mount lifecycle).
	ZfsFsCreate(*ZfsFsCreate, grpc.ServerStreamingServer[TaskEvent]) error
	ZfsSetMountpoint(*ZfsSetMountpoint, grpc.ServerStreamingServer[TaskEvent]) error
	ZfsMount(*ZfsMount, grpc.ServerStreamingServer[TaskEvent]) error
	ZfsUnmount(*ZfsUnmount, grpc.ServerStreamingServer[TaskEvent]) error
	ZfsDestroy(*ZfsDestroy, grpc.ServerStreamingServer[TaskEvent]) error
	// ZFS pools.
	PoolCreate(*PoolCreate, grpc.ServerStreamingServer[TaskEvent]) error
	PoolVdevAdd(*PoolVdevAdd, grpc.ServerStreamingServer[TaskEvent]) error
	PoolDeviceAttach(*PoolDeviceAttach, grpc.ServerStreamingServer[TaskEvent]) error
	PoolDeviceRemove(*PoolDeviceRemove, grpc.ServerStreamingServer[TaskEvent]) error
	PoolDeviceDetach(*PoolDeviceDetach, grpc.ServerStreamingServer[TaskEvent]) error
	// Partitioning (sfdisk); PartitionShrink is the compound fs+partition op.
	PartitionTableCreate(*PartitionTableCreate, grpc.ServerStreamingServer[TaskEvent]) error
	PartitionCreate(*PartitionCreate, grpc.ServerStreamingServer[TaskEvent]) error
	PartitionDelete(*PartitionDelete, grpc.ServerStreamingServer[TaskEvent]) error
	PartitionShrink(*PartitionShrink, grpc.ServerStreamingServer[TaskEvent]) error
	// LVM.
	LvmReport(*LvmReport, grpc.ServerStreamingServer[TaskEvent]) error
	VgCreate(*VgCreate, grpc.ServerStreamingServer[TaskEvent]) error
	VgExtend(*VgExtend, grpc.ServerStreamingServer[TaskEvent]) error
	VgReduce(*VgReduce, grpc.ServerStreamingServer[TaskEvent]) error
	VgRemove(*VgRemove, grpc.ServerStreamingServer[TaskEvent]) error
	LvCreate(*LvCreate, grpc.ServerStreamingServer[TaskEvent]) error
	ThinPoolCreate(*ThinPoolCreate, grpc.ServerStreamingServer[TaskEvent]) error
	ThinLvCreate(*ThinLvCreate, grpc.ServerStreamingServer[TaskEvent]) error
	LvResize(*LvResize, grpc.ServerStreamingServer[TaskEvent]) error
	LvShrink(*LvShrink, grpc.ServerStreamingServer[TaskEvent]) error
	LvRename(*LvRename, grpc.ServerStreamingServer[TaskEvent]) error
	LvDelete(*LvDelete, grpc.ServerStreamingServer[TaskEvent]) error
	// Desired-state reconcile pass (the only apply path for NVMe-oF/iSCSI/NFS).
	Reconcile(*Reconcile, grpc.ServerStreamingServer[TaskEvent]) error
	// CSI exports: imperative, idempotent, and restricted by type to the CSI NQN
	// prefix — a sibling of (not nested under) the web prefix, so reconcile
	// treats CSI subsystems as foreign and the two owners never fight. They live
	// on a dedicated CSI port, never a render-managed one.
	CsiNvmeApply(*CsiNvmeApply, grpc.ServerStreamingServer[TaskEvent]) error
	CsiNvmeDelete(*CsiNvmeDelete, grpc.ServerStreamingServer[TaskEvent]) error
	CsiHostGrant(*CsiHostGrant, grpc.ServerStreamingServer[TaskEvent]) error
	CsiHostRevoke(*CsiHostRevoke, grpc.ServerStreamingServer[TaskEvent]) error
	CsiVolumeExpand(*CsiVolumeExpand, grpc.ServerStreamingServer[TaskEvent]) error
	ZfsClone(*ZfsClone, grpc.ServerStreamingServer[TaskEvent]) error
	// SSH keys authorized to open a `greendotctl pipe` session (the CSI
	// controller's login today). The daemon owns the forced command.
	PipeKeyAdd(*PipeKeyAdd, grpc.ServerStreamingServer[TaskEvent]) error
	PipeKeyRevoke(*PipeKeyRevoke, grpc.ServerStreamingServer[TaskEvent]) error
	// System setup.
	RxeAdd(*RxeAdd, grpc.ServerStreamingServer[TaskEvent]) error
	EnableRoce(*EnableRoce, grpc.ServerStreamingServer[TaskEvent]) error
	SetMtu(*SetMtu, grpc.ServerStreamingServer[TaskEvent]) error
	InstallPackages(*InstallPackages, grpc.ServerStreamingServer[TaskEvent]) error
	// Tool-output reads (streamed; the web collects stdout verbatim).
	SmartReport(*SmartReport, grpc.ServerStreamingServer[TaskEvent]) error
	RdmaResources(*Empty, grpc.ServerStreamingServer[TaskEvent]) error
	// Structural reads: typed actual-state replies.
	NfsReport(context.Context, *Empty) (*NfsReportReply, error)
	NvmetReport(context.Context, *Empty) (*NvmetReportReply, error)
	LioReport(context.Context, *Empty) (*LioReportReply, error)
	LioSessions(context.Context, *Empty) (*LioSessionsReply, error)
	RdmaDevices(context.Context, *Empty) (*RdmaDevicesReply, error)
	NicPciAddrs(context.Context, *Empty) (*NicPciAddrsReply, error)
	NicInterfaces(context.Context, *Empty) (*NicInterfacesReply, error)
	NicNetwork(context.Context, *Empty) (*NicNetworkReply, error)
	RoceCapableNics(context.Context, *Empty) (*RoceCapableNicsReply, error)
	NicRdmaAdvice(context.Context, *Empty) (*NicRdmaAdviceReply, error)
	SmartHealth(context.Context, *SmartHealth) (*SmartHealthReply, error)
	ReconcileDryRun(context.Context, *Empty) (*ReconcileDryRunReply, error)
	ZvolInfo(context.Context, *ZvolInfo) (*ZvolInfoReply, error)
	PipeAccessReport(context.Context, *Empty) (*PipeAccessReportReply, error)
	mustEmbedUnimplementedHelperServer()
}

